  "labels": [
    {
      "label": "M_PayToProgress",
      "span": "set up in a pay to win way",
      "rule_applied": "Pay to Win (Hadan et al. 2024) [low-level]",
      "rationale": "The reviewer states the game grants advantage to players who pay."
